export function makeQuestion(q: typeof QUESTION_BANK[0], order: number) {
  return {
    questionText: q.q,
    options: q.opts.map((text, i) => ({ id: ["a","b","c","d"][i], text })),
    correctOptionId: q.ans,
    explanation: q.exp,
    subject: q.sub,
    difficulty: q.diff,
    marks: 2,
    negativeMarks: 0.5,
    order,
    language: "English",
  };
}

